import csv
import io

def summarize_expenses(csv_text):
    totals = {}
    for row in csv.DictReader(io.StringIO(csv_text)):
        cat = row['category']
        totals[cat] = round(totals.get(cat, 0.0) + float(row['amount']), 2)
    return totals

