import csv
import io

def summarize_expenses(csv_text):
    totals = {}
    reader = csv.reader(io.StringIO(csv_text))
    next(reader, None)
    for row in reader:
        if not row:
            continue
        cat, amt = row[0], float(row[1])
        totals[cat] = round(totals.get(cat, 0.0) + amt, 2)
    return totals

